/* Host-side tests for the DLL's own zlib inflate + PNG decoder (src/fw_png.c; 3D phase M3: the image a .glb embeds).
 * The fixtures test/fixtures/png/<name>.png are GENERATED by the editor (editor/src/core/art/png-fixtures.ts, written by
 * editor/scripts/make-fw3d-assets.ts; editor/test/glb-texture-tests.ts keeps committed == generated): its encoder
 * (png.ts encodePng) and Node's zlib with stored / fixed / dynamic Huffman blocks, every scanline filter, every 8-bit
 * colour type, tRNS, several IDATs and an ancillary chunk; <name>.rgba.hex is the expected straight RGBA8 (hex text).
 * The broken ones must be refused with the right code, never read past their end. */
#define FW_NO_WINDOWS
#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include "../../test/minitest.h"
#include "fw_png.h"

static uint8_t *read_file(const char *rel, size_t *len) {
    char path[1024];
    const char *f = __FILE__, *slash = NULL;
    for (const char *p = f; *p; p++) if (*p == '/' || *p == '\\') slash = p;
    size_t dir = slash ? (size_t)(slash - f + 1) : 0;
    if (dir + strlen(rel) + 1 > sizeof path) return NULL;
    memcpy(path, f, dir); strcpy(path + dir, rel);
    FILE *fp = fopen(path, "rb");
    if (!fp) { printf("      cannot open fixture %s\n", path); return NULL; }
    fseek(fp, 0, SEEK_END); long sz = ftell(fp); fseek(fp, 0, SEEK_SET);
    uint8_t *b = (uint8_t *)malloc(sz > 0 ? (size_t)sz : 1);
    *len = fread(b, 1, (size_t)(sz > 0 ? sz : 0), fp);
    fclose(fp);
    return b;
}
static int hexv(int c) { return c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : -1; }
/* the .rgba.hex text -> bytes (whitespace / CR ignored) */
static uint8_t *read_hex(const char *rel, size_t *len) {
    size_t n = 0; uint8_t *t = read_file(rel, &n);
    if (!t) return NULL;
    uint8_t *o = (uint8_t *)malloc(n / 2 + 1);
    size_t k = 0; int hi = -1;
    for (size_t i = 0; i < n; i++) {
        int v = hexv(t[i]);
        if (v < 0) continue;
        if (hi < 0) hi = v; else { o[k++] = (uint8_t)(hi * 16 + v); hi = -1; }
    }
    free(t);
    *len = k;
    return o;
}

/* decodes fixtures/png/<name>.png and compares with <name>.rgba.hex */
static void good(const char *name, int w, int h) {
    char rel[128];
    size_t n = 0, hn = 0;
    snprintf(rel, sizeof rel, "fixtures/png/%s.png", name);
    uint8_t *png = read_file(rel, &n);
    snprintf(rel, sizeof rel, "fixtures/png/%s.rgba.hex", name);
    uint8_t *want = read_hex(rel, &hn);
    if (!png || !want) { MT_FAIL("fixture %s missing", name); free(png); free(want); return; }
    FwPngImage img;
    char why[160];
    int rc = fw_png_decode(png, n, 2048, &img, why, sizeof why);
    if (rc != FW_PNGD_OK) MT_FAIL("%s: code %d: %s", name, rc, why);
    else {
        CHECK_EQ(img.w, w); CHECK_EQ(img.h, h);
        CHECK_EQ(hn, (size_t)w * h * 4);
        if (hn == (size_t)img.w * img.h * 4 && memcmp(img.rgba, want, hn) != 0) MT_FAIL("%s: decoded pixels differ from %s.rgba.hex", name, name);
    }
    fw_png_free(&img);
    free(png); free(want);
}
static int bad(const char *name, char *why, size_t cap) {
    char rel[128];
    size_t n = 0;
    snprintf(rel, sizeof rel, "fixtures/png/%s.png", name);
    uint8_t *png = read_file(rel, &n);
    if (!png) return -1;
    FwPngImage img;
    int rc = fw_png_decode(png, n, 2048, &img, why, cap);
    CHECK(img.rgba == NULL);
    free(png);
    return rc;
}

TEST(png_editor_encoder_rgba) { good("rgba-encoder", 5, 4); }
TEST(png_rgb_every_filter_level9) { good("rgb-filters", 7, 6); }
TEST(png_rgb_stored_blocks) { good("rgb-stored", 7, 6); }
TEST(png_rgba_fixed_huffman) { good("rgba-fixed", 9, 5); }
TEST(png_grey) { good("grey", 6, 3); }
TEST(png_grey_trns_key) { good("grey-trns", 4, 2); }
TEST(png_rgb_trns_key) { good("rgb-trns", 3, 2); }
TEST(png_grey_alpha) { good("grey-alpha", 5, 3); }
TEST(png_palette_trns) { good("palette-trns", 6, 4); }
TEST(png_three_idats_and_text_chunk) { good("multi-idat", 8, 8); }
TEST(png_dynamic_huffman_64x48) { good("big-dynamic", 64, 48); }

TEST(png_broken_ones_are_refused_with_a_code) {
    char why[160];
    CHECK_EQ(bad("bad-crc", why, sizeof why), FW_PNGD_CORRUPT);       CHECK(strstr(why, "CRC") != NULL);
    CHECK_EQ(bad("bad-adler", why, sizeof why), FW_PNGD_CORRUPT);     CHECK(strstr(why, "Adler") != NULL);
    CHECK_EQ(bad("bad-deflate", why, sizeof why), FW_PNGD_CORRUPT);
    CHECK_EQ(bad("truncated", why, sizeof why), FW_PNGD_CORRUPT);     CHECK(strstr(why, "truncated") != NULL);
    CHECK_EQ(bad("bad-filter", why, sizeof why), FW_PNGD_CORRUPT);    CHECK(strstr(why, "filter type 7") != NULL);
    CHECK_EQ(bad("interlaced", why, sizeof why), FW_PNGD_UNSUPPORTED); CHECK(strstr(why, "interlaced") != NULL);
    CHECK_EQ(bad("depth16", why, sizeof why), FW_PNGD_UNSUPPORTED);   CHECK(strstr(why, "bit depth 16") != NULL);
    CHECK_EQ(bad("unknown-critical", why, sizeof why), FW_PNGD_UNSUPPORTED); CHECK(strstr(why, "QXYZ") != NULL);
    CHECK_EQ(bad("zero-size", why, sizeof why), FW_PNGD_SIZE);
    CHECK_EQ(bad("not-png", why, sizeof why), FW_PNGD_NOT_PNG);
}

TEST(png_size_cap_and_null_input) {
    size_t n = 0; uint8_t *png = read_file("fixtures/png/big-dynamic.png", &n);
    FwPngImage img; char why[160];
    CHECK_EQ(fw_png_decode(png, n, 32, &img, why, sizeof why), FW_PNGD_SIZE);   /* 64 x 48 over a 32 cap */
    CHECK(strstr(why, "64x48") != NULL);
    CHECK_EQ(fw_png_decode(NULL, 0, 0, &img, why, sizeof why), FW_PNGD_NOT_PNG);
    for (size_t cut = 0; png && cut < n; cut += 97) {               /* every prefix: refused, never a read past it */
        int rc = fw_png_decode(png, cut, 0, &img, NULL, 0);
        CHECK(rc != FW_PNGD_OK);
        fw_png_free(&img);
    }
    free(png);
}

TEST(zlib_inflate_header_checks_and_capacity) {
    /* zlib.deflateSync(Buffer.from("abcabcabc"), { level: 9 }) = 78da4b4c4a4e042300113d0373 */
    static const uint8_t z[] = { 0x78, 0xda, 0x4b, 0x4c, 0x4a, 0x4e, 0x04, 0x23, 0x00, 0x11, 0x3d, 0x03, 0x73 };
    uint8_t out[16]; size_t got = 0; char why[128];
    CHECK_EQ(fw_zlib_inflate(z, sizeof z, out, sizeof out, &got, why, sizeof why), 0);
    CHECK_EQ(got, 9); CHECK(memcmp(out, "abcabcabc", 9) == 0);
    CHECK_EQ(fw_zlib_inflate(z, sizeof z, out, 8, &got, why, sizeof why), -1);   /* one byte too small */
    CHECK(strstr(why, "more image data") != NULL);
    uint8_t bad[sizeof z]; memcpy(bad, z, sizeof z); bad[1] ^= 1;                   /* FCHECK */
    CHECK_EQ(fw_zlib_inflate(bad, sizeof bad, out, sizeof out, &got, why, sizeof why), -1);
    CHECK(strstr(why, "FCHECK") != NULL);
    memcpy(bad, z, sizeof z); bad[0] = 0x79;                                        /* method 9 */
    CHECK_EQ(fw_zlib_inflate(bad, sizeof bad, out, sizeof out, &got, why, sizeof why), -1);
    CHECK_EQ(fw_zlib_inflate(z, 5, out, sizeof out, &got, why, sizeof why), -1);   /* truncated */
    /* an empty stored block: 78 01 01 00 00 ff ff 00 00 00 01 */
    static const uint8_t empty[] = { 0x78, 0x01, 0x01, 0x00, 0x00, 0xff, 0xff, 0x00, 0x00, 0x00, 0x01 };
    CHECK_EQ(fw_zlib_inflate(empty, sizeof empty, out, sizeof out, &got, why, sizeof why), 0);
    CHECK_EQ(got, 0);
}

TEST(premultiply_is_the_games_rule) {
    /* Texture2D_LoadFromFile 0xa0ad40: c = (byte)(int)(c * (a * 0.00392156862745098)) */
    uint8_t px[12] = { 200, 100, 50, 255,   200, 100, 51, 128,   255, 255, 255, 0 };
    fw_png_premultiply(px, 3);
    CHECK_EQ(px[0], 200); CHECK_EQ(px[1], 100); CHECK_EQ(px[2], 50); CHECK_EQ(px[3], 255);
    CHECK_EQ(px[4], 100); CHECK_EQ(px[5], 50); CHECK_EQ(px[6], 25); CHECK_EQ(px[7], 128);   /* 200*128/255 = 100.39 -> 100 */
    CHECK_EQ(px[8], 0); CHECK_EQ(px[11], 0);
}

int main(void) { return MT_RUN_ALL(); }
